import { describe, expect, it, vi, type Mock } from 'vitest';
import type { ChangeLogEntry } from '@asohav/shared';
import * as supabaseMod from './supabase.js';
import { appendChangeLog, listChangeLog, getChangeLogEntry } from './repo.js';

describe('appendChangeLog', () => {
  let insertMock: Mock;

  beforeEach(() => {
    insertMock = vi.fn();
    (supabaseMod.suriseAdmin as any).from.mockImplementation((tableName: string) => {
      return {
        insert: insertMock,
        select: vi.fn().mockImplementation((query: unknown) => {
          const mockResult = {
            data: [],
            error: null,
            count: 0,
          };
          const response = vi.fn(() => mockResult);
          if (tableName === 'changelog') {
            response.order = vi.fn().mockImplementation((orderArg: unknown) => response);
            response.limit = vi.fn().mockImplementation((limitArg: unknown) => response);
            response.eq = vi.fn().mockImplementation((arg: unknown) => {
              const mock = vi.fn(response);
              mock.maybeSingle = vi.fn().mockResolvedValue(mockResult as any);
              return mock;
            });
          }
          response.maybeSingle = vi.fn().mockResolvedValue(mockResult as any);
          return response;
        }),
      };
    });
  });

  it('inserts without including an id key in the payload', async () => {
    const entry: Omit<ChangeLogEntry, 'Id' | 'At'> = {
      who: 'test-user',
      action: 'create',
      collection: 'moves',
      object_id: 'move-test',
      object_name: 'Test Move',
      before: { field: 'old' },
      after: { field: 'new' },
    };

    await appendChangeLog(entry);

    expect(insertMock).toHaveBeenCalled();
    const payload = (insertMock.mock.calls[0][0] as any);
    expect(payload).not.toHaveProperty('id');
    expect(payload).not.toHaveProperty('Id');
  });

  it('inserts all required changelog columns mapped to snake_case', async () => {
    const entry: Omit<ChangeLogEntry, 'Id' | 'At'> = {
      who: 'test-user',
      action: 'update',
      collection: 'monsters',
      object_id: 'monster-test',
      object_name: 'Test Monster',
      before: { hitPoints: 20 },
      after: { hitPoints: 25 },
    };

    await appendChangeLog(entry);

    const payload = (insertMock.mock.calls[0][0] as any);
    expect(payload).toHaveProperty('at');
    expect(payload).toHaveProperty('who', entry.who);
    expect(payload).toHaveProperty('action', entry.action);
    expect(payload).toHaveProperty('collection', entry.collection);
    expect(payload).toHaveProperty('object_id', entry.object_id);
    expect(payload).toHaveProperty('object_name', entry.object_name);
    expect(payload).toHaveProperty('before', entry.before);
    expect(payload).toHaveProperty('after', entry.after);
  });

  it('propagates errors from the insert call', async () => {
    const error = new Error('Insert failed');
    (insertMock as any).mockImplementationOnce(() => {
      throw error;
    });

    const entry: Omit<ChangeLogEntry, 'Id' | 'At'> = {
      who: 'test-user',
      action: 'delete',
      collection: 'locations',
      object_id: 'loc-test',
      object_name: 'Test Location',
      before: { description: 'A cave' },
      after: { description: '' },
    };

    await expect(appendChangeLog(entry)).rejects.toThrow(error);
  });
});

describe('listChangeLog', () => {
  it('returns ChangeLogEntry array with camelCase properties', async () => {
    const mockRows = [
      {
        id: 'uuid-123',
        at: '2024-01-01T00:00:00Z',
        who: 'user-1',
        action: 'create',
        collection: 'moves',
        object_id: 'move-1',
        object_name: 'Test Move',
        before: null,
        after: { field: 'value' },
      },
    ];
    (supabaseMod.suriseAdmin as any).from.mockImplementation((tableName: string) => {
