import { describe, expect, it, vi, beforeEach } from 'vitest';
import type { ChangeLogEntry } from '@asohav/shared';
import * as repoMod from './repo.js';
import { appendChangeLog, listChangeLog, getChangeLogEntry } from './repo.js';

describe('appendChangeLog', () => {
  beforeEach(() => {
    vi.resetAllMocks();
  });
  it('inserts without including an id key in the payload', async () => {
    const entry: Omit<ChangeLogEntry, 'Id' | 'At'> = {
      who: 'test-user',
      action: 'create',
      collection: 'moves',
      object_id: 'move-test',
      object_name: 'Test Move',
      before: { field: 'old' },
      after: { field: 'new' },
    };

    // Mock the supabase client call made by appendChangeLog
    vi.mocked(repoMod.supabaseAdmin).from.mockReturnValue({
      insert: vi.fn(),
      select: vi.fn().mockReturnValue({
        order: vi.fn().mockReturnValue({
          limit: vi.fn().mockReturnValue({
            eq: vi.fn().mockReturnValue({
              maybeSingle: vi.fn().mockResolvedValue({ data: [], error: null })
            })
          })
        })
      })
    });

    await appendChangeLog(entry);

    const insertCall = vi.mocked(repoMod.supabaseAdmin).from.mock.calls[0][0];
    const payload = vi.mocked(insertCall).mock.calls[0][0];

    expect(payload).not.toHaveProperty('id');
    expect(payload).not.toHaveProperty('Id');
  });

  it('inserts all required changelog columns mapped to snake_case', async () => {
    const entry: Omit<ChangeLogEntry, 'Id' | 'At'> = {
      who: 'test-user',
      action: 'update',
      collection: 'monsters',
      object_id: 'monster-test',
      object_name: 'Test Monster',
      before: { hitPoints: 20 },
      after: { hitPoints: 25 },
    };

    vi.mocked(repoMod.supabaseAdmin).from.mockReturnValue({
      insert: vi.fn().mockResolvedValue({ error: null }),
      select: vi.fn().mockReturnValue({
        order: vi.fn().mockReturnValue({
          limit: vi.fn().mockReturnValue({
            eq: vi.fn().mockReturnValue({
              maybeSingle: vi.fn().mockResolvedValue({ data: [], error: null })
            })
          })
        })
      })
    });

    await appendChangeLog(entry);

    const insertCall = vi.mocked(repoMod.supabaseAdmin).from.mock.calls[0][0];
    const payload = vi.mocked(insertCall).mock.calls[0][0];

    expect(payload.at).toBeDefined();
    expect(payload.who).toBe(entry.who);
    expect(payload.action).toBe(entry.action);
    expect(payload.collection).toBe(entry.collection);
    expect(payload.object_id).toBe(entry.object_id);
    expect(payload.object_name).toBe(entry.object_name);
    expect(payload.before).toEqual(entry.before);
    expect(payload.after).toEqual(entry.after);
  });

  it('propagates errors from the insert call', async () => {
    const error = new Error('Insert failed');
    const mockInsert = vi.fn().mockImplementation(() => { throw error; });

    vi.mocked(repoMod.supabaseAdmin).from.mockReturnValue({
      insert: mockInsert,
      select: vi.fn().mockReturnValue({
        order: vi.fn().mockReturnValue({
          limit: vi.fn().mockReturnValue({
            eq: vi.fn().mockReturnValue({
              maybeSingle: vi.fn().mockResolvedValue({ data: [], error: null })
            })
          })
        })
      })
    });

    const entry: Omit<ChangeLogEntry, 'Id' | 'At'> = {
      who: 'test-user',
      action: 'delete',
      collection: 'locations',
      object_id: 'loc-test',
      object_name: 'Test Location',
      before: { description: 'A cave' },
      after: { description: '' },
    };

    await expect(appendChangeLog(entry)).rejects.toThrow(error);
  });
});

describe('listChangeLog', () => {
  beforeEach(() => {
    vi.resetAllMocks();
  });
  it('returns ChangeLogEntry array with camelCase properties', async () => {
    const mockRows = [
      {
        id: 'uuid-123',
        at: '2024-01-01T00:00:00Z',
        who: 'user-1',
        action: 'create',
        collection: 'moves',
        object_id: 'move-1',
        object_name: 'Test Move',
        before: null,
        after: { field: 'value' },
      },
    ];

    vi.mocked(repoMod.supabaseAdmin).from.mockReturnValue({
      select: vi.fn().mockReturnValue({
        order: vi.fn().mockReturnValue({
          limit: vi.fn().mockReturnValue({
            eq: vi.fn().mockReturnValue({
              maybeSingle: vi.fn()
            }),
            maybeSingle: vi.fn().mockResolvedValue({ data: mockRows, error: null })
          })
        }),
        maybeSingle: vi.fn()
      })
    });

    const result = await listChangeLog(200);

    expect(result).toHaveLength(1);
    expect(result[0].Id).toBe('uuid-123');
    expect(result[0].At).toBe('2024-01-01T00:00:00Z');
    expect(result[0].Who).toBe('user-1');
  });
});

describe('getChangeLogEntry', () => {
  it('returns the entry with camelCase properties', async () => {
    const mockRow = {
      id: 'uuid-123',
      at: '2024-01-01T00:00:00Z',
      who: 'user-1',
      action: 'delete',
      collection: 'locations',
      object_id: 'loc-1',
      object_name: 'Test Location',
      before: { description: 'A cave' },
      after: { description: '' },
    };

    vi.mocked(repoMod.supabaseAdmin).from.mockReturnValue({
      select: vi.fn().mockReturnValue({
        eq: vi.fn().mockReturnValue({
          maybeSingle: vi.fn().mockResolvedValue({ data: mockRow, error: null })
        })
      })
    });

    const result = await getChangeLogEntry('uuid-123');

    expect(result).not.toBeNull();
    expect(result!.Id).toBe('uuid-123');
    expect(result!.Action).toBe('delete');
  });

  it('returns null when no entry is found', async () => {
    vi.mocked(repoMod.supabaseAdmin).from.mockReturnValue({
      select: vi.fn().mockReturnValue({
        eq: vi.fn().mockReturnValue({
          maybeSingle: vi.fn().mockResolvedValue({ data: null, error: null })
        })
      })
    });

    const result = await getChangeLogEntry('non-existent-id');

    expect(result).toBeNull();
  });
});

